+/*
+ * Maps Starlight's own --sl-* theme variables onto the Gramaire tokens in
+ * tokens.css, so the docs chrome (nav, sidebar, search, code blocks) themes
+ * from the same single palette instead of Starlight's defaults.
+ *
+ * Starlight toggles [data-theme="dark"|"light"] on <html> itself, the same
+ * attribute tokens.css keys off — no separate dark-mode wiring needed here.
+ *
+ * Deliberate contrast change (IMPLEMENTATION_astro.md §1): the old site used
+ * #15b879 as the UI/text accent. That value is now --node (logomark only);
+ * the UI/text accent is the AA-contrast --accent (#0a8f63 light / #34d399
+ * dark). Do not reintroduce #15b879 as a text or control color here.
+ */
+
+:root {
+  --sl-font: var(--font-ui);
+  --sl-font-mono: var(--font-mono);
+
+  --sl-color-accent-low: var(--accent-softer);
+  --sl-color-accent: var(--accent);
+  --sl-color-accent-high: var(--accent-2);
+  --sl-color-text-accent: var(--accent);
+
+  --sl-color-white: var(--fg);
+  --sl-color-black: var(--bg);
+  --sl-color-gray-1: var(--bg-3);
+  --sl-color-gray-2: var(--bg-2);
+  --sl-color-gray-3: var(--border-strong);
+  --sl-color-gray-4: var(--border);
+  --sl-color-gray-5: var(--fg-faint);
+  --sl-color-gray-6: var(--bg-1);
+  --sl-color-gray-7: var(--bg-1);
+
+  --sl-color-bg: var(--bg);
+  --sl-color-bg-nav: var(--bg);
+  --sl-color-bg-sidebar: var(--bg);
+  --sl-color-bg-inline-code: var(--bg-2);
+  --sl-color-hairline-light: var(--border);
+  --sl-color-hairline: var(--border);
+  --sl-color-hairline-shade: var(--border-strong);
+  --sl-color-text: var(--fg-secondary);
+}
+
+.site-title {
+  font-weight: 700;
+  letter-spacing: -0.04em;
+}

